const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const scoreEl = document.getElementById('score-el');
        const finalScoreEl = document.getElementById('final-score');
        const startOverlay = document.getElementById('start-overlay');
        const gameOverOverlay = document.getElementById('game-over-overlay');
        const sensorStatus = document.getElementById('sensor-status');
        const sensorDot = document.getElementById('sensor-dot');
        const debugX = document.getElementById('debug-x');
        const debugY = document.getElementById('debug-y');
        let isPlaying = false;
        let score = 0;
        let scoreInterval;
        // Liquid Physics Variables
        let liquid = { x: 0, y: 0, vx: 0, vy: 0, radius: 0 };
        let cup = { x: 0, y: 0, radius: 0 };
        let tilt = { x: 0, y: 0 };
        // Physics constants (tuned for "heavy liquid" feel)
        const FRICTION = 0.96;
        const SPRING = 0.04;
        const SENSITIVITY = 1.2;
        // Resize Canvas and Center Elements
        function resize() {
            // Get parent container dimensions
            const rect = canvas.parentElement.getBoundingClientRect();
            // High DPI scaling
            const dpr = window.devicePixelRatio || 1;
            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;
            // Scale context
            ctx.scale(dpr, dpr);
            // Logic Dimensions (CSS pixels)
            const width = rect.width;
            const height = rect.height;
            // Recalculate dimensions relative to screen size
            cup.x = width / 2;
            cup.y = height / 2;
            cup.radius = Math.min(width, height) * 0.35;
            liquid.radius = cup.radius * 0.85;
            // If just resizing, center the liquid (if not playing)
            if (!isPlaying) {
                liquid.x = cup.x;
                liquid.y = cup.y;
            }
        }
        window.addEventListener('resize', resize);
        // Initial call after small delay to ensure DOM layout
        setTimeout(resize, 100);
        // Game Loop
        function update() {
            if (!isPlaying) return;
            // 1. Physics: Calculate target position based on tilt
            let targetX = cup.x + (tilt.x * cup.radius * SENSITIVITY);
            let targetY = cup.y + (tilt.y * cup.radius * SENSITIVITY);
            // 2. Spring Physics (Hooke's Law approximation)
            let ax = (targetX - liquid.x) * SPRING;
            let ay = (targetY - liquid.y) * SPRING;
            liquid.vx += ax;
            liquid.vy += ay;
            liquid.vx *= FRICTION;
            liquid.vy *= FRICTION;
            liquid.x += liquid.vx;
            liquid.y += liquid.vy;
            // 3. Collision Detection (Spill Check)
            // Distance between cup center and liquid center
            let dx = liquid.x - cup.x;
            let dy = liquid.y - cup.y;
            let dist = Math.sqrt(dx * dx + dy * dy);
            // Limit checks: Distance + Liquid Radius > Cup Radius
            if (dist + liquid.radius > cup.radius) {
                gameOver();
            }
            // 4. Drawing
            const width = canvas.width / (window.devicePixelRatio || 1);
            const height = canvas.height / (window.devicePixelRatio || 1);
            ctx.clearRect(0, 0, width, height);
            // Draw Cup Body (Background of cup)
            ctx.beginPath();
            ctx.arc(cup.x, cup.y, cup.radius, 0, Math.PI * 2);
            ctx.fillStyle = '#ffffff';
            ctx.shadowColor = 'rgba(0,0,0,0.05)';
            ctx.shadowBlur = 30;
            ctx.shadowOffsetY = 10;
            ctx.fill();
            ctx.shadowBlur = 0; // Reset shadow
            ctx.shadowOffsetY = 0;
            // Cup Rim
            ctx.lineWidth = 12;
            ctx.strokeStyle = '#cbd5e1';
            ctx.stroke();
            // Draw Liquid (Coffee)
            ctx.beginPath();
            ctx.arc(liquid.x, liquid.y, liquid.radius, 0, Math.PI * 2);
            ctx.fillStyle = '#4B2C20';
            ctx.fill();
            // Liquid Reflection (Crescent)
            ctx.beginPath();
            ctx.arc(liquid.x - liquid.radius * 0.2, liquid.y - liquid.radius * 0.2, liquid.radius * 0.9, 0, Math.PI * 2);
            ctx.fillStyle = 'rgba(255,255,255,0.03)';
            ctx.fill();
            // Specular Highlight (The "shiny" part)
            ctx.beginPath();
            ctx.ellipse(liquid.x + liquid.radius * 0.4, liquid.y - liquid.radius * 0.4, liquid.radius * 0.2, liquid.radius * 0.1, Math.PI / 4, 0, Math.PI * 2);
            ctx.fillStyle = 'rgba(255,255,255,0.15)';
            ctx.fill();
            // Foam Bubbles (Procedural visual flair)
            const time = Date.now() * 0.001;
            drawBubble(liquid.x + Math.sin(time) * 10, liquid.y + Math.cos(time) * 10, liquid.radius * 0.1);
            drawBubble(liquid.x - liquid.radius * 0.3 + Math.cos(time * 2) * 5, liquid.y + liquid.radius * 0.2, liquid.radius * 0.08);
            requestAnimationFrame(update);
        }
        function drawBubble(x, y, r) {
            ctx.beginPath();
            ctx.arc(x, y, r, 0, Math.PI * 2);
            ctx.fillStyle = '#6F4E37';
            ctx.fill();
        }
        // Input Handling
        function handleOrientation(event) {
            // Beta: Front to back (-180 to 180). We only care about +/- 45
            // Gamma: Left to right (-90 to 90).
            let x = event.gamma; // Left/Right
            let y = event.beta;  // Front/Back
            // Null check (for desktop or non-sensor devices)
            if (x === null || y === null) return;
            // Basic Clamp to +/- 45 degrees
            if (x > 45) x = 45;
            if (x < -45) x = -45;
            if (y > 45) y = 45;
            if (y < -45) y = -45;
            // Normalize to -1 to 1 range
            tilt.x = x / 45;
            tilt.y = y / 45;
            // Debug UI
            debugX.innerText = Math.round(x);
            debugY.innerText = Math.round(y);
        }
        // Mouse Fallback for Desktop Testing
        document.addEventListener('mousemove', (e) => {
            if (!isPlaying) return;
            // Map mouse position to tilt for testing
            const rect = canvas.getBoundingClientRect();
            const cx = rect.left + rect.width / 2;
            const cy = rect.top + rect.height / 2;
            // Normalize mouse from center (-1 to 1) relative to half screen
            tilt.x = (e.clientX - cx) / (rect.width / 2);
            tilt.y = (e.clientY - cy) / (rect.height / 2);
            // Clamp for mouse
            tilt.x = Math.max(-1, Math.min(1, tilt.x));
            tilt.y = Math.max(-1, Math.min(1, tilt.y));
            debugX.innerText = (tilt.x * 45).toFixed(0);
            debugY.innerText = (tilt.y * 45).toFixed(0);
        });
        // Game State Management
        async function requestPermissionAndStart() {
            // iOS 13+ requires permission
            if (typeof DeviceOrientationEvent !== 'undefined' && typeof DeviceOrientationEvent.requestPermission === 'function') {
                try {
                    const permissionState = await DeviceOrientationEvent.requestPermission();
                    if (permissionState === 'granted') {
                        startGame();
                    } else {
                        alert('Permission denied. The game needs gyroscope access to balance the coffee.');
                    }
                } catch (e) {
                    console.error(e);
                    // Fallback try (sometimes works on non-https environments)
                    startGame();
                }
            } else {
                // Android / Desktop / Older iOS
                startGame();
            }
        }
        function startGame() {
            // Add listener
            window.addEventListener('deviceorientation', handleOrientation);
            // UI Update
            startOverlay.classList.add('opacity-0', 'pointer-events-none');
            gameOverOverlay.classList.add('hidden');
            gameOverOverlay.classList.remove('flex', 'opacity-100');
            sensorStatus.innerText = "ACTIVE";
            sensorStatus.className = "text-green-500 font-bold tracking-widest";
            sensorDot.className = "w-2 h-2 rounded-full bg-green-500 animate-pulse";
            // Reset Physics
            liquid.x = cup.x;
            liquid.y = cup.y;
            liquid.vx = 0;
            liquid.vy = 0;
            tilt.x = 0;
            tilt.y = 0;
            score = 0;
            scoreEl.innerText = score;
            isPlaying = true;
            // Start Score Counter
            if (scoreInterval) clearInterval(scoreInterval);
            scoreInterval = setInterval(() => {
                if (isPlaying) {
                    score += 13; // Arbitrary score points to make numbers look bigger/cooler
                    scoreEl.innerText = score;
                }
            }, 100);
            // Start Loop
            update();
        }
        function gameOver() {
            isPlaying = false;
            clearInterval(scoreInterval);
            // We don't remove listener immediately so user can still see debug values
            // window.removeEventListener('deviceorientation', handleOrientation);
            finalScoreEl.innerText = score;
            // Shake effect on container
            const container = document.getElementById('game-container');
            container.classList.add('shake');
            setTimeout(() => container.classList.remove('shake'), 500);
            // Show Overlay
            gameOverOverlay.classList.remove('hidden', 'opacity-0');
            gameOverOverlay.classList.add('flex', 'opacity-100');
            sensorStatus.innerText = "CRASHED";
            sensorStatus.className = "text-red-500 font-bold tracking-widest";
            sensorDot.className = "w-2 h-2 rounded-full bg-red-500";
        }
        function resetGame() {
            // Trigger start logic again
            resize(); // Ensure size is correct
            startGame();
        }
        // Initial setup
        resize();
